import itertools
from pysat.solvers import Glucose3

def solve_ramsey():
    n = 22
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    edge_to_idx = {edge: i + 1 for i, edge in enumerate(edges)}

    solver = Glucose3()

    # No red clique of size 5 (color 0)
    # For every subset of 5 vertices, at least one edge must be blue (1)
    for subset in itertools.combinations(range(n), 5):
        clause = []
        for i, j in itertools.combinations(subset, 2):
            clause.append(edge_to_idx[(i, j)])
        solver.add_clause(clause)

    # No blue clique of size 4 (color 1)
    # For every subset of 4 vertices, at least one edge must be red (0)
    for subset in itertools.combinations(range(n), 4):
        clause = []
        for i, j in itertools.combinations(subset, 2):
            clause.append(-edge_to_idx[(i, j)])
        solver.add_clause(clause)

    if solver.solve():
        model = solver.get_model()
        # model contains values for each edge_to_idx (1 to 231)
        # If model[i] > 0, edge is 1 (blue), if model[i] < 0, edge is 0 (red)
        result = []
        for i in range(1, 232):
            if model[i-1] > 0:
                result.append(1)
            else:
                result.append(0)
        return result
    else:
        return None

