def check_coloring(n, coloring):
    edges = {}
    idx = 0
    for i in range(n):
        for j in range(i + 1, n):
            edges[(i, j)] = coloring[idx]
            idx += 1

    # Check red cliques of size 5 (color 0)
    import itertools
    for subset in itertools.combinations(range(n), 5):
        is_red = True
        for i, j in itertools.combinations(subset, 2):
            if edges[(i, j)] != 0:
                is_red = False
                break
        if is_red:
            return False, f"Red clique found: {subset}"

    # Check blue cliques of size 4 (color 1)
    for subset in itertools.combinations(range(n), 4):
        is_blue = True
        for i, j in itertools.combinations(subset, 2):
            if edges[(i, j)] != 1:
                is_blue = False
                break
        if is_blue:
            return False, f"Blue clique found: {subset}"

    return True, "No monochromatic cliques found"

